#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[1005]; int counts[1005] = {0}, uniq[1005], u_len = 0;
    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
        int found = -1;
        for (int j = 0; j < u_len; j++) if (uniq[j] == a[i]) { found = j; break; }
        if (found != -1) counts[found]++;
        else { uniq[u_len] = a[i]; counts[u_len++] = 1; }
    }
    for (int i = 0; i < u_len; i++) printf("%d:%d\n", uniq[i], counts[i]);
    return 0;
}

code.C++:
#include <iostream>
#include <vector>
#include <map>
using namespace std;
int main() {
    int n; if (!(cin >> n)) return 0;
    vector<long long> order;
    map<long long, int> counts;
    for (int i = 0; i < n; i++) {
        long long x; cin >> x;
        if (counts[x] == 0) order.push_back(x);
        counts[x]++;
    }
    for (long long x : order) cout << x << ":" << counts[x] << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
import java.util.LinkedHashMap;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            LinkedHashMap<Long, Integer> map = new LinkedHashMap<>();
            for (int i = 0; i < n; i++) {
                long x = sc.nextLong();
                map.put(x, map.getOrDefault(x, 0) + 1);
            }
            for (var entry : map.entrySet()) {
                System.out.println(entry.getKey() + ":" + entry.getValue());
            }
        }
    }
}

